svg.script:
(function() {
  var root = document.querySelector('.a12p22-root');
  if (!root) return;

  var modeBtns = root.querySelectorAll('.a12p22-btn-mode');
  var items = root.querySelectorAll('.a12p22-item');
  var labels = root.querySelectorAll('.a12p22-label-group');

  var panelTitle = root.querySelector('#a12p22-panel-title');
  var panelCat = root.querySelector('#a12p22-panel-cat');
  var panelDesc = root.querySelector('#a12p22-panel-desc');
  var panelAnchor = root.querySelector('#a12p22-panel-anchor');
  var panelAnchorContainer = root.querySelector('#a12p22-anchor-container');

  var currentMode = 'full';
  var activeItemId = 'pubococcigeo';

  function setMode(mode) {
    currentMode = mode;
    root.setAttribute('data-mode', mode);

    modeBtns.forEach(function(btn) {
      if (btn.getAttribute('data-target-mode') === mode) {
        btn.classList.add('a12p22-btn-active');
        btn.setAttribute('aria-pressed', 'true');
      } else {
        btn.classList.remove('a12p22-btn-active');
        btn.setAttribute('aria-pressed', 'false');
      }
    });

    if (mode === 'active') {
      labels.forEach(function(lbl) {
        lbl.classList.remove('a12p22-label-revealed');
      });
    } else {
      labels.forEach(function(lbl) {
        lbl.classList.add('a12p22-label-revealed');
      });
    }

    updatePanel();
  }

  function selectItem(el) {
    if (!el) return;

    items.forEach(function(item) {
      item.classList.remove('a12p22-selected');
      item.setAttribute('aria-selected', 'false');
    });

    el.classList.add('a12p22-selected');
    el.setAttribute('aria-selected', 'true');
    activeItemId = el.getAttribute('data-id');

    // Reveal corresponding label if in active retrieval mode
    var targetLblId = 'lbl-' + activeItemId;
    var targetLbl = root.querySelector('#' + targetLblId);
    if (targetLbl) {
      targetLbl.classList.add('a12p22-label-revealed');
    }

    updatePanel(el);
  }

  function updatePanel(el) {
    if (!el) {
      el = root.querySelector('.a12p22-item[data-id="' + activeItemId + '"]');
    }
    if (!el) return;

    var name = el.getAttribute('data-name') || '';
    var cat = el.getAttribute('data-category') || '';
    var desc = el.getAttribute('data-desc') || '';
    var anchor = el.getAttribute('data-anchor') || '';
    var color = el.getAttribute('data-color') || 'var(--a12p22-text, #F7F1F5)';

    if (panelTitle) panelTitle.textContent = name;
    if (panelCat) {
      panelCat.textContent = cat;
      panelCat.style.color = color;
    }
    if (panelDesc) panelDesc.textContent = desc;
    if (panelAnchor) panelAnchor.textContent = anchor;

    if (panelAnchorContainer) {
      if (currentMode === 'anchor' || currentMode === 'full') {
        panelAnchorContainer.style.opacity = '1';
      } else {
        panelAnchorContainer.style.opacity = '0.35';
      }
    }
  }

  // Attach button events
  modeBtns.forEach(function(btn) {
    btn.addEventListener('click', function() {
      setMode(btn.getAttribute('data-target-mode'));
    });
    btn.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setMode(btn.getAttribute('data-target-mode'));
      }
    });
  });

  // Attach item events
  items.forEach(function(item) {
    item.addEventListener('click', function() {
      selectItem(item);
    });
    item.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        selectItem(item);
      }
    });
  });

  // Initial state setup
  setMode('full');
  var defaultEl = root.querySelector('.a12p22-item[data-id="pubococcigeo"]');
  if (defaultEl) selectItem(defaultEl);
})();
